Here is a simple JavaScript example demonstrating how to optimize CPU utilization in a browser context without causing user disruption:
```javascript
// Example: Basic CPU throttling
function throttle(fn, delay) {
  let lastCall = 0;
  return function() {
    const now = Date.now();
    const remaining = delay - (now - lastCall);
    if (remaining <= 0) {
      fn();
      lastCall = now;
    }
  };
}

// Usage
const throttledFn = throttle(() => {
  // Your CPU-intensive work
  // Example: Fetch data from API
  fetch('https://api.example.com/data')
    .then(res => res.json())
    .then(data => console.log(data));
}, 500);
```

